class EngineModule18:
    """
    EngineModule18 implementation supporting process(data) and get_status().
    """
    def __init__(self):
        self._status = "ready"
        self._last_processed_data = None

    def process(self, data):
        """
        Process the incoming data and update internal state/status.
        """
        self._last_processed_data = data
        self._status = "success"

        if isinstance(data, dict):
            res = dict(data)
            res['status'] = 'success'
            return res
        elif isinstance(data, (int, float, str)):
            return {'data': data, 'status': 'success'}
        return {'input': data, 'status': 'success'}

    def get_status(self):
        """
        Return the current status of the engine module.
        """
        return self._status
